        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            int size = Integer.parseInt(br.readLine());
            String str = br.readLine();
            br.close();

            int maxLen = 0;
            int currentLen = 0;
            boolean insideBrackets = false;
            ArrayList<Integer> lengths = new ArrayList<>();
            lengths.add(0);
            char[] chArr = str.toCharArray();

            for (char ch : chArr) {
                if (ch == '(') {
                    insideBrackets = true;
                    if (currentLen != 0) {
                        lengths.add(currentLen);
                    }
                    currentLen = 0;
                } else if (ch == ')') {
                    insideBrackets = false;
                } else if (!insideBrackets && ch != '_') {
                    currentLen++;
                } else if (!insideBrackets && ch == '_') {
                    lengths.add(currentLen);
                    currentLen = 0;
                }
            }
            if (currentLen != 0) {
                lengths.add(currentLen);
            }

            System.out.print(Collections.max(lengths) + " ");

            int verbCounter = 0;
            int countInBrackets = 0;
            boolean inBrackets = false;
            for (char ch : chArr) {
                if (ch == '(') {
                    inBrackets = true;
                    countInBrackets = 0;
                } else if (ch == ')') {
                    inBrackets = false;
                    if (countInBrackets != 0) {
                        verbCounter++;
                    }
                } else if (inBrackets && ch != '_') {
                    countInBrackets++;
                } else if (inBrackets && ch == '_') {
                    if (countInBrackets != 0) {
                        verbCounter++;
                    }
                    countInBrackets = 0;
                }
            }

            System.out.print(verbCounter);
        } catch (Exception e) {
